function afipCertKey(array $flags = []): void
{
    buildApp(); // bootstrap del entorno (.env) para leer afip.key_path

    $path = (string) (\App\Support\Config::get('afip.key_path') ?: BASE_PATH . '/storage/afip/private.key');

    if (is_file($path) && !in_array('--force', $flags, true)) {
        error("Ya existe la clave en {$path}. Usá --force para sobrescribir.");
    }

    $key = openssl_pkey_new(['private_key_bits' => 2048, 'private_key_type' => OPENSSL_KEYTYPE_RSA]);
    if ($key === false || !openssl_pkey_export($key, $pem)) {
        error('No se pudo generar la clave privada con openssl.');
    }

    @mkdir(dirname($path), 0770, true);
    if (file_put_contents($path, $pem) === false) {
        error("No se pudo escribir la clave en {$path}.");
    }
    @chmod($path, 0600);

    line("<green>Clave privada RSA 2048 generada</green>: {$path}");
    line('  Configurá <yellow>AFIP_KEY_PATH</yellow> en .env si aún no apunta ahí.');
    line('  Siguiente: php modux afip:cert-csr "<Common Name>"');
    echo PHP_EOL;
}

