function afipCertCsr(?string $commonName, array $flags = []): void
{
    if (!$commonName) {
        error('Usage: php modux afip:cert-csr "<Common Name>" [--org="<Organización>"] [--country=AR]');
    }

    buildApp(); // bootstrap del entorno (.env)

    $keyPath = (string) (\App\Support\Config::get('afip.key_path') ?: BASE_PATH . '/storage/afip/private.key');
    $cuit    = preg_replace('/\D/', '', (string) (\App\Support\Config::get('afip.cuit') ?? '')) ?? '';

    if (!is_file($keyPath)) {
        error("No existe la clave privada en {$keyPath}. Generala con: php modux afip:cert-key");
    }
    if (strlen($cuit) !== 11) {
        error('AFIP_CUIT inválido o ausente en .env (deben ser 11 dígitos).');
    }

    $key = openssl_pkey_get_private((string) file_get_contents($keyPath));
    if ($key === false) {
        error("No se pudo leer la clave privada en {$keyPath}.");
    }

    // ARCA identifica al titular por el CUIT en el campo serialNumber del subject.
    $dn = [
        'countryName'      => strtoupper(flagValue($flags, '--country', 'AR')),
        'organizationName' => flagValue($flags, '--org', $commonName),
        'commonName'       => $commonName,
        'serialNumber'     => "CUIT {$cuit}",
    ];

    $csr = openssl_csr_new($dn, $key, ['digest_alg' => 'sha256']);
    if ($csr === false || !openssl_csr_export($csr, $pem)) {
        error('No se pudo generar el CSR con openssl.');
    }

    $csrPath = dirname($keyPath) . '/request.csr';
    if (file_put_contents($csrPath, $pem) === false) {
        error("No se pudo escribir el CSR en {$csrPath}.");
    }

    line("<green>CSR generado</green>: {$csrPath}");
    line('  Subilo al portal WSASS de ARCA y asociá los servicios (wsfe / ws_sr_padron_a5).');
    line('  Guardá el certificado emitido en la ruta de <yellow>AFIP_CERT_PATH</yellow>.');
