import { useEffect, useState } from 'react'
import { useQuery } from '@tanstack/react-query'
import {
  CModal,
  CModalHeader,
  CModalTitle,
  CModalBody,
  CModalFooter,
  CFormSelect,
  CFormLabel,
  CButton,
  CBadge,
  CSpinner,
  CAlert,
} from '@coreui/react'
import { listPeriodos } from '../../api/periodos'

interface Props {
  visible: boolean
  empresaId: number
  periodoActualId: number
  /** Descripción del comprobante a mover (para el encabezado). */
  detalle?: string
  moving: boolean
  errorMsg?: string | null
  onClose: () => void
  onMove: (periodoDestinoId: number) => void
}

/** Mueve un comprobante de venta/compra a otro período de la misma empresa.
 * Réplica del "Mover" del Visual IVA. Lista los períodos de la empresa excluyendo
 * el actual; el backend valida que el destino esté abierto. */
export default function MoverComprobanteModal({
  visible,
  empresaId,
  periodoActualId,
  detalle,
  moving,
  errorMsg,
  onClose,
  onMove,
}: Props) {
  const { data: periodos, isLoading } = useQuery({
    queryKey: ['periodos', empresaId],
    queryFn: () => listPeriodos(empresaId),
    enabled: visible,
  })

  const destinos = (periodos ?? []).filter((p) => p.id !== periodoActualId)
  const [destino, setDestino] = useState('')

  useEffect(() => {
    if (visible) setDestino('')
  }, [visible])

  return (
    <CModal visible={visible} onClose={onClose} alignment="center">
      <CModalHeader>
        <CModalTitle>Mover comprobante</CModalTitle>
      </CModalHeader>

    enabled: visible,
  })

  const destinos = (periodos ?? []).filter((p) => p.id !== periodoActualId)
  const [destino, setDestino] = useState('')

  useEffect(() => {
    if (visible) setDestino('')
  }, [visible])

  return (
    <CModal visible={visible} onClose={onClose} alignment="center">
      <CModalHeader>
        <CModalTitle>Mover comprobante</CModalTitle>
      </CModalHeader>
      <CModalBody>
        {errorMsg && <CAlert color="danger">{errorMsg}</CAlert>}
        {detalle && <p className="mb-3">Mover {detalle} a otro período.</p>}
        {isLoading && <CSpinner />}
        {!isLoading && destinos.length === 0 && (
          <CAlert color="warning" className="mb-0">
            No hay otros períodos disponibles en esta empresa.
          </CAlert>
        )}
        {destinos.length > 0 && (
          <>
            <CFormLabel htmlFor="periodo-destino">Período destino</CFormLabel>
            <CFormSelect
              id="periodo-destino"
              value={destino}
              onChange={(e) => setDestino(e.target.value)}
            >
              <option value="">— Elegí un período —</option>
              {destinos.map((p) => (
                <option key={p.id} value={p.id} disabled={p.cerrado === 'S'}>
                  {p.nombre} {p.cerrado === 'S' ? '(cerrado)' : ''}
                </option>
              ))}
            </CFormSelect>
            <div className="text-body-secondary small mt-2">
              Los períodos <CBadge color="secondary">cerrados</CBadge> no admiten comprobantes.
            </div>
          </>
        )}
      </CModalBody>
      <CModalFooter>
        <CButton color="secondary" variant="outline" onClick={onClose}>
          Cancelar
        </CButton>
        <CButton
          color="primary"
          disabled={moving || !destino}
          onClick={() => destino && onMove(Number(destino))}
        >
          {moving ? 'Moviendo…' : 'Mover'}
        </CButton>
      </CModalFooter>
    </CModal>
  )
}

import { useRef, useState } from 'react'
import { CFormInput } from '@coreui/react'
import type { Sujeto } from '../../api/sujetos'

interface Props {
  sujetos: Sujeto[] | undefined
  /** Texto actual (nombre/razón social del comprobante). */
  value: string
  /** El usuario tipeó (queda como sujeto ocasional hasta elegir uno de la lista). */
  onText: (text: string) => void
  /** Eligió un sujeto del padrón del estudio (autocompleta datos fiscales). */
  onPick: (s: Sujeto) => void
  placeholder?: string
  id?: string
}

/** Búsqueda inteligente de cliente/proveedor (réplica del Visual IVA): tipeás nombre o
 * CUIT y se despliega la lista de coincidencias; al elegir uno se autocompletan sus datos.
 * Filtra sobre el listado ya cargado (sin llamadas extra). */
export default function SujetoTypeahead({ sujetos, value, onText, onPick, placeholder, id }: Props) {
  const [open, setOpen] = useState(false)
  const blurTimer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)

  const q = value.trim().toLowerCase()
  const qDigits = q.replace(/\D/g, '')
  const matches =
    q.length < 2
      ? []
      : (sujetos ?? [])
          .filter(
            (s) =>
              s.nombre.toLowerCase().includes(q) ||
              (qDigits.length >= 2 && (s.cuit ?? '').replace(/\D/g, '').includes(qDigits)),
          )
          .slice(0, 8)

  const pick = (s: Sujeto) => {
    onPick(s)
    setOpen(false)
  }

  return (
    <div className="position-relative">
      <CFormInput
        id={id}
        autoComplete="off"
        placeholder={placeholder}
        value={value}
        onChange={(e) => {
          onText(e.target.value)
          setOpen(true)
        }}
        onFocus={() => setOpen(true)}
        onBlur={() => {
          blurTimer.current = setTimeout(() => setOpen(false), 150)
        }}
      />
      {open && matches.length > 0 && (
        <div
          className="position-absolute w-100 bg-body border rounded shadow-sm"

        autoComplete="off"
        placeholder={placeholder}
        value={value}
        onChange={(e) => {
          onText(e.target.value)
          setOpen(true)
        }}
        onFocus={() => setOpen(true)}
        onBlur={() => {
          blurTimer.current = setTimeout(() => setOpen(false), 150)
        }}
      />
      {open && matches.length > 0 && (
        <div
          className="position-absolute w-100 bg-body border rounded shadow-sm"
          style={{ zIndex: 1060, maxHeight: 220, overflowY: 'auto', top: '100%' }}
          onMouseDown={() => clearTimeout(blurTimer.current)}
        >
          {matches.map((s) => (
            <button
              key={s.id}
              type="button"
              className="dropdown-item text-body px-3 py-1 text-start w-100 border-0 bg-transparent"
              onClick={() => pick(s)}
            >
              {s.nombre}
              {s.cuit ? <span className="text-body-secondary small"> · {s.cuit}</span> : null}
            </button>
          ))}
        </div>
      )}
    </div>
  )
}

