        tipoComprobanteId: fila.tipo_comprobante_id,
        puntoVenta: fila.punto_venta,
        letra: fila.letra,
        numero,
      })
      setDetalle(d)
    } catch (e) {
      setDetalleError(apiError(e))
    } finally {
      setCargandoDetalle(false)
    }
  }

  setCargandoDetalle(true)
