    $stmt = $this->pdo->prepare('SELECT * FROM jobs WHERE id = ? LIMIT 1');
    $stmt->execute([$jobId]);
    $row = $stmt->fetch(\PDO::FETCH_ASSOC);
    return $row !== false ? $row : null;
}

