    private static function resolveKey(array $data, ?string $key, mixed $default): mixed
    {
        if ($key === null) {
            return $data;
        }

        foreach (explode('.', $key) as $segment) {
            if (!is_array($data) || !array_key_exists($segment, $data)) {
                return $default;
            }
            $data = $data[$segment];
        }

        return $data;
    }
}

        match ($this->channelConfig['driver'] ?? 'stderr') {
