): string {
    $out  = $this->lineasGravadoDebito($actividad, $gravadoNormal, '1');
    $out .= $this->lineasGravadoDebito($actividad, $gravadoBienUso, '2');

    if (!Decimal::of($noGravado)->isZero()) {
        $out .= $this->linea([$actividad, '3', '', '', '', '', '', $this->monto($noGravado)]);
    }

    return $out;
}

