/**
 * Reagrupa las filas gravadas (que vienen por condición de IVA + alícuota) por
 * tipo de sujeto comprador + alícuota, sumando neto e IVA. Saltea exportación.
 *
 * @param  list<array{condicion_iva_id: ?int, alicuota: ?string, neto: string, iva: string}> $gravado
 * @return list<array{tipo_sujeto: int, alicuota_cod: int, neto: string, iva: string}>
 */
private function agruparPorSujeto(array $gravado): array
{
    /** @var array<string, array{tipo_sujeto: int, alicuota_cod: int, neto: Decimal, iva: Decimal}> $buckets */
    $buckets = [];
    foreach ($gravado as $row) {
        $sujeto = $this->tipoSujeto($row['condicion_iva_id'] !== null ? (int) $row['condicion_iva_id'] : null);
        if ($sujeto === null) {
            continue;
        }
        $cod = $this->codigoAlicuota($row['alicuota']);
        $key = "{$sujeto}|{$cod}";
        if (!isset($buckets[$key])) {
            $buckets[$key] = [
                'tipo_sujeto'  => $sujeto,
                'alicuota_cod' => $cod,
                'neto'         => Decimal::zero(),
                'iva'          => Decimal::zero(),
            ];
        }
        $buckets[$key]['neto'] = $buckets[$key]['neto']->add(Decimal::of($row['neto']));
        $buckets[$key]['iva']  = $buckets[$key]['iva']->add(Decimal::of($row['iva']));
    }

    $out = [];
    foreach ($buckets as $b) {
        $out[] = [
            'tipo_sujeto'  => $b['tipo_sujeto'],
            'alicuota_cod' => $b['alicuota_cod'],
            'neto'         => $b['neto']->value(2),

                    'alicuota_cod' => $cod,
                    'neto'         => Decimal::zero(),
                    'iva'          => Decimal::zero(),
                ];
            }
            $buckets[$key]['neto'] = $buckets[$key]['neto']->add(Decimal::of($row['neto']));
            $buckets[$key]['iva']  = $buckets[$key]['iva']->add(Decimal::of($row['iva']));
        }

        $out = [];
        foreach ($buckets as $b) {
            $out[] = [
                'tipo_sujeto'  => $b['tipo_sujeto'],
                'alicuota_cod' => $b['alicuota_cod'],
                'neto'         => $b['neto']->value(2),
                'iva'          => $b['iva']->value(2),
            ];
        }

        return $out;
    }
}

    /** CUIT de 11 dígitos a "AA-BBBBBBBB-C" (13 chars). Si no tiene 11 dígitos, lo deja como viene, acotado a 13. */
    private function cuit(string $cuit): string
    {
        $d = preg_replace('/\D/', '', $cuit) ?? '';
        if (strlen($d) === 11) {
            return substr($d, 0, 2) . '-' . substr($d, 2, 8) . '-' . substr($d, 10, 1);
        }

        return str_pad(substr($d, 0, 13), 13);
    }

    /** 'Y-m-d' → 'd/m/Y' (10 chars). */
    private function fecha(string $ymd): string
    {
        if (preg_match('/^(\d{4})-(\d{2})-(\d{2})/', $ymd, $m)) {
            return "{$m[3]}/{$m[2]}/{$m[1]}";
        }

        return str_pad('', 10);
    }

    /** Importe a "00003679,72" (8 enteros + ',' + 2 decimales). */
    private function importe(int|float|string|null $valor): string
    {
        $v = Decimal::of((string) ($valor ?? 0))->abs()->value(2); // "3679.72"
        [$ent, $dec] = explode('.', $v . '.0');
        $ent = substr(str_pad($ent, 8, '0', STR_PAD_LEFT), -8);

        return $ent . ',' . str_pad(substr($dec, 0, 2), 2, '0');
    }
