/**
 * Listado paginado y filtrado del período. Los nombres de columna del WHERE son
 * literales del código; los valores van por placeholders (sin inyección).
 *
 * @param array{
 *   fecha_desde?: ?string, fecha_hasta?: ?string, proveedor_id?: ?int,
 *   cuit?: ?string, letra?: ?string, nombre?: ?string, numero?: ?string, orden?: ?string
 * } $filtros
 * @return array<string, mixed> total / cantidad_por_pagina / pagina / results
 */
public function findPaginado(int $periodoId, array $filtros, int $page, int $perPage): array
{
    $where  = ['periodo_id = ?'];
    $params = [$periodoId];

    if (!empty($filtros['fecha_desde'])) {
        $where[]  = 'fecha >= ?';
        $params[] = $filtros['fecha_desde'];
    }
    if (!empty($filtros['fecha_hasta'])) {
        $where[]  = 'fecha <= ?';
        $params[] = $filtros['fecha_hasta'];
    }
    if (!empty($filtros['proveedor_id'])) {
        $where[]  = 'proveedor_id = ?';
        $params[] = (int) $filtros['proveedor_id'];
    }
    if (!empty($filtros['cuit'])) {
        $where[]  = 'cuit = ?';
        $params[] = $filtros['cuit'];
    }
    if (!empty($filtros['letra'])) {
        $where[]  = 'letra = ?';
        $params[] = $filtros['letra'];
    }
    if (!empty($filtros['nombre'])) {
        $where[]  = 'proveedor_nombre LIKE ?';
        $params[] = '%' . $filtros['nombre'] . '%';
    }
    if (!empty($filtros['numero'])) {
        $where[]  = 'numero LIKE ?';

    }
    if (!empty($filtros['cuit'])) {
        $where[]  = 'cuit = ?';
        $params[] = $filtros['cuit'];
    }
    if (!empty($filtros['letra'])) {
        $where[]  = 'letra = ?';
        $params[] = $filtros['letra'];
    }
    if (!empty($filtros['nombre'])) {
        $where[]  = 'proveedor_nombre LIKE ?';
        $params[] = '%' . $filtros['nombre'] . '%';
    }
    if (!empty($filtros['numero'])) {
        $where[]  = 'numero LIKE ?';
        $params[] = '%' . $filtros['numero'] . '%';
    }

    // Orden por lista blanca (nombres de columna fijos, no input crudo del usuario).
    $orden = match ($filtros['orden'] ?? '') {
        'fecha_desc' => 'fecha DESC, id DESC',
        'nombre'     => 'proveedor_nombre, fecha, id',
        'numero'     => 'CAST(numero AS UNSIGNED), id',
        'total'      => 'total, id',
        'total_desc' => 'total DESC, id',
        default      => 'fecha, id',
    };
    // Neto e IVA derivados de las discriminaciones, para verlos en el listado sin abrir el
    // comprobante (pedido del contador). Subqueries correlacionadas: el WHERE/ORDER usa las
    // columnas de `compras` (único base del query externo).
    $query = 'SELECT c.*,'
        . ' (SELECT COALESCE(SUM(cd.neto_gravado), 0) FROM compra_discriminaciones cd'
        . '   WHERE cd.compra_id = c.id) AS neto_gravado,'
        . ' (SELECT COALESCE(SUM(cd.iva_importe), 0) FROM compra_discriminaciones cd'
        . '   WHERE cd.compra_id = c.id) AS iva'
        . ' FROM compras c WHERE ' . implode(' AND ', $where) . ' ORDER BY ' . $orden;

    return (new PaginatorHelper($this->pdo, $query, $page, $perPage, true, $params))->getPaginatedResults();
}

