        $set = implode(', ', array_map(static fn (string $c) => "{$c} = :{$c}", array_keys($fields)));
        $fields['id']         = $id;
        $fields['periodo_id'] = $periodoId;
        $stmt = $this->pdo->prepare("UPDATE compras SET {$set} WHERE id = :id AND periodo_id = :periodo_id");
        $stmt->execute($fields);
    }

