        . '    FROM venta_discriminaciones vd WHERE vd.venta_id = v.id) AS iva'
        . ' FROM ventas v WHERE ' . implode(' AND ', $where) . ' ORDER BY ' . $orden;

    return (new PaginatorHelper($this->pdo, $query, $page, $perPage, true, $params))->getPaginatedResults();
