        ]);

        $out[] = [
            'tipo_retencion_id' => $perc['tipo_retencion_id'],
            'provincia_id'      => $perc['provincia_id'] ?? ($tipo['provincia_id'] ?? null),
            'base'              => $calc['base'],
            'alicuota'          => $calc['alicuota'],
            'importe'           => $calc['importe'],
        ];
    }

    return $out;
