        if (!isset($porAct[$act])) {
            $porAct[$act] = ['normal' => [], 'bien_uso' => [], 'no_grav' => '0'];
        }
    };

    foreach ($gravado as $row) {
        $act = $row['actividad_codigo'] ?? $default;
        $ref($act);
