    $this->pdo->beginTransaction();
    try {
        $stmt = $this->pdo->prepare(
            'DELETE FROM roles_permisos WHERE rol = ? AND permiso = ?'
        );
        foreach ($permisoIds as $permisoId) {
            $stmt->execute([$rolId, $permisoId]);
        }
        $this->pdo->commit();
    } catch (\PDOException $e) {
        $this->pdo->rollBack();
        throw $e;
    }
}

