    $grandparent = $this->createRol('Director');
    $parent      = $this->createRol('Manager', $grandparent);
    $child       = $this->createRol('Analyst', $parent);

    $this->assignPermiso($grandparent, $permiso, PermissionChecker::LEVEL_READ);

