        )['json']['data']['id'];
        $c1 = (int) $this->postJson("/empresas/{$e}/conceptos", [
            'codigo' => '001', 'descripcion' => 'Basico', 'formula' => 'BASICO', 'tipo' => 1,
        ], $auth)['json']['data']['id'];
        $this->postJson("/empresas/{$e}/contribuciones", [
            'descripcion' => 'Jub (SIPA)', 'porcentaje' => '10', 'aplica_detraccion' => 'S',
        ], $auth);

