        $d = $this->postJson("{$base}/contribuciones", [], $auth)['json']['data'];
        // base 1.000.000 − 300.000 = 700.000 → 10% = 70.000
        $this->assertSame('700000.00', $d['lineas'][0]['base_imponible']);
        $this->assertSame('300000.00', $d['lineas'][0]['detraccion']);
