const CODIGO_LIBRO: Record<Libro, number> = { compras: 21, ventas: 31 };

/**
 * Job de `ajax.do?f=listaTareas` (Portal IVA). Solo se tipan los campos que
 * usamos; la respuesta trae varios más (ver exploración en vivo 2026-07-26).
 */
interface TareaImportacion {
  codigo: number;
  estado: string; // "TE" = Terminada (confirmado en vivo); otros valores no relevados
  progresoActualEstimado: number; // 0-100
  fechaCreacion: string;
}

interface RespuestaListaTareas {
  estado: string;
  datos: TareaImportacion[];
}

/**
 * Poll de `ajax.do?f=listaTareas&c={21|31}` (mismo endpoint que alimenta el
 * modal "Historial de Importaciones...") hasta que la tarea más reciente
 * quede en estado "TE" (Terminada) — confirmado en vivo contra un job real
 * ya completado. Preferido sobre clickear "ACTUALIZAR" en loop (ver plan de
 * factibilidad §Polling): un fetch autenticado por cookie es más rápido y
 * no depende de que el modal esté abierto.
 *
 * Devuelve la tarea final. Tira error si se agota el timeout sin terminar.
 */
export async function esperarImportacion(
  page: Page,
  libro: Libro,
  opts: { timeoutMs?: number; intervaloMs?: number } = {},
): Promise<TareaImportacion> {
  const timeoutMs = opts.timeoutMs ?? 120_000;
  const intervaloMs = opts.intervaloMs ?? 3_000;
  const codigo = CODIGO_LIBRO[libro];
  const limite = Date.now() + timeoutMs;

  while (Date.now() < limite) {
    const respuesta = (await page.evaluate(async (c) => {
      const res = await fetch(`ajax.do?f=listaTareas&c=${c}`, { credentials: "include" });
      return res.json();
    }, codigo)) as RespuestaListaTareas;

    if (respuesta.estado !== "ok") {
      throw new Error(`listaTareas respondió estado=${respuesta.estado}`);
    }

    const [ultima] = [...respuesta.datos].sort((a, b) => b.codigo - a.codigo);
    if (ultima && ultima.estado === "TE") {
      return ultima;
    }

    await new Promise((resolve) => setTimeout(resolve, intervaloMs));
  }

  throw new Error(

